import{_ as t}from"./chunks/chamber.CbJ6774w.js";import{_ as e,o as r,c as o,a0 as s}from"./chunks/framework.BTg7EidG.js";const n="/athanor-docs/screens/main-menu.png",i="/athanor-docs/screens/class-pick.png",l="/athanor-docs/screens/guild-confirm.png",_=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),d={name:"getting-started.md"};function h(g,a,u,c,p,m){return r(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><p>Grab the latest <strong>Android APK</strong> from the <a href="https://github.com/Xander-Rudolph/athanor/releases" target="_blank" rel="noreferrer">releases page</a> — pick the <code>arm64-v8a</code> file for modern phones — and sideload it (your browser will offer to install it; allow installs from that source if asked). The game plays in landscape.</p><h2 id="starting-a-campaign" tabindex="-1">Starting a campaign <a class="header-anchor" href="#starting-a-campaign" aria-label="Permalink to &quot;Starting a campaign&quot;">​</a></h2><p><img src="'+n+'" alt="Main menu"></p><p>The game opens on a short intro cinematic — tap <strong>Skip ▸</strong> any time to jump straight to the menu, or let it play out and the menu arrives on its final frame.</p><p>From the main menu choose <strong>New Game</strong> (or <strong>Custom World</strong> to pick the world seed — the same seed always forges the same world). <strong>Continue</strong> lights up once you have a campaign saved.</p><h3 id="_1-choose-your-lord-s-calling" tabindex="-1">1. Choose your Lord&#39;s calling <a class="header-anchor" href="#_1-choose-your-lord-s-calling" aria-label="Permalink to &quot;1. Choose your Lord&#39;s calling&quot;">​</a></h3><p><img src="'+i+'" alt="Choosing a class"></p><p>Your Lord is the guild: if they fall, the campaign is lost. Each calling plays differently:</p><ul><li><strong>Warrior</strong> — front-line steel. Their <em>Rally</em> hardens the whole party.</li><li><strong>Alchemist</strong> — fragile, but opens battles with a devastating <em>Transmute Blast</em> of raw Essence.</li><li><strong>Rogue</strong> — fastest on the road, deadliest from ambush, and the only calling that can <em>sneak</em> parties through dungeon floors.</li></ul><h3 id="_2-choose-your-guild" tabindex="-1">2. Choose your guild <a class="header-anchor" href="#_2-choose-your-guild" aria-label="Permalink to &quot;2. Choose your guild&quot;">​</a></h3><p><img src="'+t+'" alt="The chamber of eight"></p><p>Tap a pedestal to hear each guild&#39;s story. Every guild has a home terrain, a sworn rival, and a distinct perk — Sulfur&#39;s blades hit harder, Aether marches faster, Aurum&#39;s vaults run deeper. Entropy sits the chamber but cannot be chosen: it is the enemy of all.</p><h3 id="_3-lore-difficulty-and-go" tabindex="-1">3. Lore, difficulty, and go <a class="header-anchor" href="#_3-lore-difficulty-and-go" aria-label="Permalink to &quot;3. Lore, difficulty, and go&quot;">​</a></h3><p><img src="'+l+'" alt="Confirming your guild"></p><p>The final screen shows your Lord&#39;s exact starting stats and your guild&#39;s story. Pick a difficulty — <strong>Easy</strong> doubles your opening treasury, <strong>Hard</strong> fattens every rival&#39;s — and press <strong>Choose</strong>.</p><h2 id="your-first-days" tabindex="-1">Your first days <a class="header-anchor" href="#your-first-days" aria-label="Permalink to &quot;Your first days&quot;">​</a></h2><p>You start with your Lord and two followers in your capital city. Your own <strong>Grand Athanor</strong> stands nearby, held by the Faithless Marauders — liberating it is your first quest, and it pays: renown for your Lord, followers and infamy for your guild, and its income and territory afterward.</p><p>From there the shape of the campaign is simple to say and long to do: grow your ring of territory, raise heroes and armies, and fight inward toward the world&#39;s blighted heart, where Entropy&#39;s own Grand Athanor waits. Do not dawdle: after the opening days the blight itself creeps outward, swallowing unclaimed lands, and only territory under a guild&#39;s banners holds it back. Cutting down Entropy&#39;s roving heroes wins a battle, never the war; only that furnace-temple&#39;s fall stills the rot. <strong>Take it, and the Great Work is yours.</strong></p>',20)])])}const b=e(d,[["render",h]]);export{_ as __pageData,b as default};
